sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

   var gaRequestor = new GlideAjax('assetRequestAjaxUtils');

   gaRequestor.addParam('sysparm_name', 'getRequestorDetails');
   gaRequestor.addParam('sysparm_requestor_id', newValue);

   gaRequestor.getXMLAnswer(function (response) {

	var reqData = JSON.parse(response);

	var requestorField = g_form.getDisplayBox('requestor');

	if (reqData.vipStatus == '1') {
		if (requestorField) {
			requestorField.style.backgroundColor = 'tomato';
		}
		g_form.setValue('priority', '1');

	} else {
		if (requestorField) {
			requestorField.style.backgroundColor = '';
		}
		g_form.setValue('priority', '3');
	}

	if (reqData.company) {
		g_form.setValue('company', reqData.company);
	} else {
		g_form.clearValue('company');
	}

   });

}
